  if (persistedViewType === "markdown") {
    return "markdown";
  }
  if (persistedViewType === MANDALA_VIEW_TYPE) {
    return MANDALA_VIEW_TYPE;
  }
  if (getLeafOfFile(plugin, file, "markdown")) {
    return "markdown";
  }
